'use client';
import { useState, useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { api } from '@/lib/api';

// Sidebar — the app shell's primary navigation.
//
// NAV mirrors preview/elevate-dental-os-v2.html `const NAV` (11 sections).
// Frozen Phase-0 primitive: section agents add screens behind these routes,
// they do not edit this file.
//
// RBAC (project rule 5):
//   reception          -> CRM only: Inbox, Pipeline, Contacts. Nothing else.
//   practice_manager   -> everything EXCEPT finance, unless finance_access
//                          is Owner-toggled on (me.finance_access).
//   owner / admin       -> everything.
//
// Gate flags on a section/item:
//   requiresOwner   - owner/admin only (Wealth, System, valuation, targets)
//   requiresFinance - hidden from reception; for PM needs finance_access
//   receptionOk     - item is visible to the reception role (CRM essentials)

type NavItem = {
  id: string;
  label: string;
  requiresOwner?: boolean;
  requiresFinance?: boolean;
  receptionOk?: boolean;
};
type NavSection = {
  label: string;
  items: NavItem[];
  requiresOwner?: boolean;
  requiresFinance?: boolean;
};

const NAV: NavSection[] = [
  { label: 'Overview', items: [
    { id: 'dashboard', label: 'Command Centre' },
    { id: 'ai-insights', label: 'AI Insights' },
    { id: 'p4g-ai', label: 'Plan4Growth AI' },
    { id: 'mobile', label: 'Mobile App' },
  ]},
  { label: 'Finance', requiresFinance: true, items: [
    { id: 'cashflow', label: 'Cash Flow' },
    { id: 'profit', label: 'Profit & Loss' },
    { id: 'financial', label: 'Financial' },
    { id: 'payments', label: 'Patient Payments' },
    { id: 'valuation', label: 'Valuation', requiresOwner: true },
  ]},
  { label: 'Business Health', items: [
    { id: 'health-setup', label: 'Setup & Targets', requiresOwner: true },
    { id: 'progress', label: 'Progress Tracker' },
    { id: 'kpiscorecard', label: 'KPI Scorecard' },
  ]},
  { label: 'Operations', items: [
    { id: 'associates', label: 'Associates' },
    { id: 'staff', label: 'Staff Scheduling' },
    { id: 'pay', label: 'Associate Pay', requiresFinance: true },
    { id: 'chair', label: 'Chair Utilisation' },
    { id: 'treatments', label: 'Treatments' },
    { id: 'uda', label: 'UDA Tracker' },
  ]},
  { label: 'Intelligence', requiresFinance: true, items: [
    { id: 'scenarios', label: 'Scenarios' },
    { id: 'tax', label: 'Tax (MTD)' },
    { id: 'debt', label: 'Debt Recovery' },
    { id: 'alerts', label: 'Alerts' },
  ]},
  { label: 'Growth', items: [
    { id: 'patients', label: 'Patients' },
    { id: 'marketing', label: 'Marketing' },
    { id: 'loyalty', label: 'Loyalty & Members' },
    { id: 'reviews', label: 'Reviews' },
    { id: 'booking', label: 'Online Booking' },
    { id: 'benchmark', label: 'Benchmark' },
  ]},
  { label: 'Elevate CRM', items: [
    { id: 'crm-today', label: 'Today' },
    { id: 'inbox', label: 'Inbox', receptionOk: true },
    { id: 'pipeline', label: 'Pipeline', receptionOk: true },
    { id: 'leads', label: 'Leads' },
    { id: 'crm-enquiries', label: 'Enquiries' },
    { id: 'contacts', label: 'Contacts', receptionOk: true },
    { id: 'crm-sequences', label: 'Nurturing' },
    { id: 'crm-templates', label: 'Templates' },
    { id: 'crm-reports', label: 'CRM Reports' },
    { id: 'crm-settings', label: 'CRM Settings', requiresOwner: true },
    { id: 'workflows', label: 'Automations' },
    { id: 'pages', label: 'Landing Pages' },
  ]},
  { label: 'Wealth', requiresOwner: true, items: [
    { id: 'wealth-net', label: 'Net Worth' },
    { id: 'wealth-prop', label: 'Property' },
    { id: 'wealth-pen', label: 'Pensions' },
    { id: 'wealth-fire', label: 'FIRE Plan' },
  ]},
  { label: 'Training', items: [
    { id: 'training-library', label: 'Module Library' },
    { id: 'training-my', label: 'My Modules' },
    { id: 'training-mentorship', label: 'Mentorship Calls' },
    { id: 'training-onetoone', label: '1-to-1 Coaching' },
  ]},
  { label: 'System', requiresOwner: true, items: [
    { id: 'integrations', label: 'Integrations' },
    { id: 'team-permissions', label: 'Team Permissions' },
    { id: 'settings', label: 'Settings' },
  ]},
];

// TEMPORARY: RBAC nav-gating disabled so every page is visible while the UI
// is being built out. Flip back to true (and see [[rbac-sidebar]]) once all
// screens exist. The role logic below is intact — only the gate is bypassed.
const RBAC_ENABLED = false;

interface Me {
  role: string;
  full_name: string;
  finance_access?: boolean;
}

export function Sidebar() {
  const pathname = usePathname();
  const [me, setMe] = useState<Me | null>(null);
  const [openSections, setOpenSections] = useState<Record<string, boolean>>({});

  // Load the signed-in user once to drive role-based filtering.
  useEffect(() => {
    api('/auth/me').then(setMe).catch(() => {});
  }, []);

  const role = me?.role || 'reception';
  const isOwner = role === 'owner' || role === 'admin';
  const isReception = role === 'reception';
  // PM sees finance only when the Owner has toggled finance_access on.
  const hasFinance = isOwner || (role === 'practice_manager' && !!me?.finance_access);

  // True when the whole section should render for this role.
  function canSeeSection(s: NavSection): boolean {
    if (!RBAC_ENABLED) return true;
    if (isReception) return s.label === 'Elevate CRM';
    if (s.requiresOwner && !isOwner) return false;
    if (s.requiresFinance && !hasFinance) return false;
    return true;
  }

  // True when an individual item should render for this role.
  function canSeeItem(item: NavItem): boolean {
    if (!RBAC_ENABLED) return true;
    if (isReception) return !!item.receptionOk;
    if (item.requiresOwner && !isOwner) return false;
    if (item.requiresFinance && !hasFinance) return false;
    return true;
  }

  // Resolve a section's open/closed state: explicit toggle wins, else open
  // if it contains the active route, else open Overview + CRM by default.
  function sectionOpen(label: string, hasActive: boolean): boolean {
    if (label in openSections) return openSections[label];
    if (hasActive) return true;
    return label === 'Overview' || label === 'Elevate CRM';
  }

  return (
    <aside className="w-64 bg-card border-r border-border h-screen sticky top-0 overflow-y-auto">
      <div className="p-4 border-b border-border flex items-center gap-2">
        <div className="w-8 h-8 rounded-md bg-brand text-white flex items-center justify-center font-display font-bold">
          E
        </div>
        <Link href="/dashboard" className="font-display text-lg font-semibold text-ink">
          Elevate <span className="text-ink-muted font-normal">Dental OS</span>
        </Link>
      </div>

      {me && (
        <div className="px-3 py-2 mx-3 mt-3 bg-bg rounded-lg text-xs">
          <div className="font-semibold text-ink">{me.full_name}</div>
          <div className="text-ink-muted capitalize">{role.replace('_', ' ')}</div>
        </div>
      )}

      <nav className="p-3 space-y-1">
        {NAV.filter(canSeeSection).map((section) => {
          const items = section.items.filter(canSeeItem);
          if (items.length === 0) return null;
          const hasActive = items.some((i) => pathname === `/${i.id}`);
          const open = sectionOpen(section.label, hasActive);
          return (
            <div key={section.label}>
              <button
                onClick={() =>
                  setOpenSections((s) => ({ ...s, [section.label]: !open }))
                }
                className="w-full text-left text-[11px] uppercase tracking-wider font-semibold text-ink-muted px-3 py-2 flex justify-between items-center hover:text-ink"
              >
                <span>{section.label}</span>
                <span
                  className="text-[9px]"
                  style={{
                    transform: open ? 'rotate(90deg)' : 'none',
                    transition: 'transform 0.15s',
                  }}
                >
                  ▶
                </span>
              </button>
              {open &&
                items.map((item) => {
                  const active = pathname === `/${item.id}`;
                  return (
                    <Link
                      key={item.id}
                      href={`/${item.id}`}
                      className={`block px-6 py-2 text-sm rounded-lg mx-2 transition ${
                        active
                          ? 'bg-brand-50 text-brand font-medium'
                          : 'text-ink-muted hover:bg-bg hover:text-ink'
                      }`}
                    >
                      {item.label}
                    </Link>
                  );
                })}
            </div>
          );
        })}
      </nav>
    </aside>
  );
}
